impl Solution {
    pub fn max_k_segments_sum(nums: Vec<i64>, m: usize, k: usize) -> i128 {
        let n = nums.len();
        let mut max_sum = 0i128;

        if k == 0 {
            return 0;
        }

        if m * k > n {
            return 0;
        }

        let mut starts: Vec<usize> = Vec::new();

        fn solve(
            nums: &Vec<i64>,
            m: usize,
            k: usize,
            start_index: usize,
            current_sum: i128,
            current_segments: &mut Vec<usize>,
            max_sum: &mut i128,
        ) {
            if current_segments.len() == k {
                *max_sum = (*max_sum).max(current_sum);
                return;
            }

            if start_index >= nums.len() {
                return;
            }

            // Option 1: Don't include a segment starting at start_index
            solve(
                nums,
                m,
                k,
                start_index + 1,
                current_sum,
                current_segments,
                max_sum,
            );

            // Option 2: Include a segment starting at start_index
            if start_index + m <= nums.len() {
                current_segments.push(start_index);
                let mut segment_sum = 0i128;
                for i in 0..m {
                    segment_sum += nums[start_index + i] as i128;
                }
                solve(
                    nums,
                    m,
                    k,
                    start_index + m,
                    current_sum + segment_sum,
                    current_segments,
                    max_sum,
                );
                current_segments.pop(); // Backtrack
            }
        }

        let mut current_segments: Vec<usize> = Vec::new();
        solve(&nums, m, k, 0, 0, &mut current_segments, &mut max_sum);

        max_sum
    }
}

